// ─── Build PRISMA prompt for Ollama ───
// PROVENANCE_NEUTRE_v1 (2026-10-20, P47) : la provenance d'un import se lit sous son LIBELLE, dans la
// langue du document. L'import range un identifiant neutre (« reference-library »,
// « screening-platform-import ») ; les valeurs rangees avant ce jour et les libelles relus d'un fichier
// se lisent pareil, si bien qu'un corpus qui les mele ne donne qu'une ligne. Toute autre provenance
// (une base interrogee) reste telle quelle. COPIE A L'IDENTIQUE de src/provenance_neutre.py (`libelle`)
// et de app/src/lib/sourceReference.ts : si l'une change, changer les autres (cas qui les executent
// toutes : tests/test_provenance_neutre_du_20_10.py).
function __ulProvenanceLisible(s, lang) {
  const libelles = {
    'reference-library': ['Bibliothèque de références', 'Reference library'],
    'screening-platform-import': ['Plateforme de tri (import)', 'Screening platform (import)']
  };
  const anciennes = { 'zotero': 'reference-library', 'rayyan-import': 'screening-platform-import',
    'covidence-import': 'screening-platform-import' };
  const a = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
  if (typeof s !== 'string') return s == null ? '' : s;
  const k = s.normalize('NFC').trim().toLowerCase();
  let id = a(libelles, k) ? k : (a(anciennes, k) ? anciennes[k] : null);
  if (!id) {
    for (const i of Object.keys(libelles)) {
      if (libelles[i][0].toLowerCase() === k || libelles[i][1].toLowerCase() === k) id = i;
    }
  }
  if (!id) return s;
  return libelles[id][String(lang || '').toLowerCase().indexOf('en') === 0 ? 1 : 0];
}
const data = $input.all()[0].json;
const articles = data.articles || [];
const stats = data.stats || {};
const ris = data.ris || '';
const xlsx_base64 = data.xlsx_base64 || '';
const outputFolder = data.output_folder || '/desktop/review ultralab';

const question = (articles[0] && articles[0].question) || stats.question || '';
const criteria = (articles[0] && articles[0].criteria) || stats.criteria || '';

const total = stats.total || articles.length;
const included = stats.included || articles.filter(a => a.screening_decision === 'Include').length;
const excluded = stats.excluded || articles.filter(a => a.screening_decision === 'Exclude').length;
const maybe = stats.maybe || articles.filter(a => a.screening_decision === 'Maybe').length;
const with_pdf = stats.with_pdf || articles.filter(a => a.pdf_url).length;
// Les provenances LUES, en anglais comme ce rapport, une fois chacune (PROVENANCE_NEUTRE_v1,
// 2026-10-20) : l'invite annoncait les valeurs rangees, et un ancien et un nouvel import en double.
const sources = [...new Set((Array.isArray(stats.sources) ? stats.sources : articles.map(a => a.source))
  .map(s => __ulProvenanceLisible(s, 'en')).filter(Boolean))];
const clusters = stats.clusters || [...new Set(articles.map(a => a.cluster_label).filter(Boolean))];
const totalBeforeDedup = stats.total_before_dedup || total;
const duplicatesRemoved = stats.duplicates_removed || 0;

const topIncluded = articles
  .filter(a => a.screening_decision === 'Include')
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, 10)
  .map(a => '- ' + (a.title || '').substring(0, 100) + ' (' + (a.year || '') + ')')
  .join('\n');

const clusterSummary = clusters.map(label => {
  const count = articles.filter(a => a.cluster_label === label).length;
  return '- ' + label + ' (' + count + ' articles)';
}).join('\n');

const prompt = 'Write a PRISMA 2020 systematic review protocol report based on the following data. Be scientific, concise, and professional. Write in English.\n\nRESEARCH QUESTION: ' + question + '\n\nINCLUSION/EXCLUSION CRITERIA: ' + criteria + '\n\nSEARCH STATISTICS:\n- Databases: ' + sources.join(', ') + '\n- Total records retrieved: ' + totalBeforeDedup + '\n- Duplicates removed: ' + duplicatesRemoved + '\n- Records after deduplication: ' + total + '\n- After AI screening: Included=' + included + ' Excluded=' + excluded + ' Uncertain=' + maybe + '\n- Full text available: ' + with_pdf + '\n\nTHEMATIC CLUSTERS:\n' + (clusterSummary || 'No clusters') + '\n\nTOP INCLUDED ARTICLES:\n' + (topIncluded || 'None') + '\n\nWrite these sections (use ## for headers):\n1. Background\n2. Search Strategy\n3. Inclusion and Exclusion Criteria\n4. Results Summary\n5. Thematic Analysis\n6. Limitations\n7. Next Steps for Manual Review';

// Extract search equations from article metadata
const pubmed_query = (articles[0] && articles[0].pubmed_query) || '';
const openalex_query = (articles[0] && articles[0].openalex_query) || '';
const crossref_query = (articles[0] && articles[0].crossref_query) || '';

console.log('PRISMA prompt built: ' + prompt.length + ' chars');
console.log('Search queries found: PubMed=' + (pubmed_query ? 'yes' : 'no') + ' OpenAlex=' + (openalex_query ? 'yes' : 'no') + ' Crossref=' + (crossref_query ? 'yes' : 'no'));

return [{ json: {
  prompt, articles, stats: { total, included, excluded, maybe, with_pdf, sources, clusters, total_before_dedup: totalBeforeDedup, duplicates_removed: duplicatesRemoved },
  ris, xlsx_base64, outputFolder, question, criteria,
  total, included, excluded, maybe, with_pdf, sources, clusters, totalBeforeDedup, duplicatesRemoved,
  pubmed_query, openalex_query, crossref_query
}}];

// ─── Generate PRISMA HTML Report & Save All Files ───
const fs = require('fs');
const path = require('path');

const ollamaResp = $input.all()[0].json;
const prev = $('Build PRISMA Prompt').first().json;

const prismaText = ollamaResp.response || 'Unable to generate narrative sections. Please review the statistics below.';
const articles = prev.articles || [];
const pStats = prev.stats || {};
const ris = prev.ris || '';
const xlsx_base64 = prev.xlsx_base64 || '';
const outputFolder = prev.outputFolder || '/desktop/review ultralab';
const question = prev.question || '';
const criteria = prev.criteria || '';

const total = prev.total || 0;
const included = prev.included || 0;
const excluded = prev.excluded || 0;
const maybe = prev.maybe || 0;
const with_pdf = prev.with_pdf || 0;
const sources = prev.sources || [];
const clusters = prev.clusters || [];
const totalBeforeDedup = prev.totalBeforeDedup || total;
const duplicatesRemoved = prev.duplicatesRemoved || 0;
const pubmed_query = prev.pubmed_query || '';
const openalex_query = prev.openalex_query || '';
const crossref_query = prev.crossref_query || '';
const dateStr = new Date().toISOString().split('T')[0];

// PRISMA_ECHAPPEMENT_v1 (2026-09-20) : tout TEXTE insere dans PRISMA_Report.html passe par
// __pEsc, la fonction de l'assemblage (ultralab-module.json, « Assemble Results »). Mesure du meme
// jour sur ce noeud execute, un texte hostile par champ (balise, script, esperluette) : la reponse
// du modele, la question, les criteres, les trois equations, le titre, l'auteur, l'annee, le
// score, la grappe, la source et les noms des deux modeles ressortaient TELS QUELS, soit 21
// balises et 21 scripts bruts pour 20 champs, et une esperluette nue restait nue. Le balisage
// VOULU (titres, puces, paragraphes, tableaux) reste celui du noeud : seul le texte est echappe.
// Les compteurs du flux sont des nombres calcules par la chaine, pas du texte.
function __pEsc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

// PROVENANCE_NEUTRE_v1 (2026-10-20, P47) : la provenance d'un import se lit sous son LIBELLE, dans la
// langue du document. L'import range un identifiant neutre (« reference-library »,
// « screening-platform-import ») ; les valeurs rangees avant ce jour et les libelles relus d'un fichier
// se lisent pareil, si bien qu'un corpus qui les mele ne donne qu'une ligne. Toute autre provenance
// (une base interrogee) reste telle quelle. COPIE A L'IDENTIQUE de src/provenance_neutre.py (`libelle`)
// et de app/src/lib/sourceReference.ts : si l'une change, changer les autres (cas qui les executent
// toutes : tests/test_provenance_neutre_du_20_10.py).
function __ulProvenanceLisible(s, lang) {
  const libelles = {
    'reference-library': ['Bibliothèque de références', 'Reference library'],
    'screening-platform-import': ['Plateforme de tri (import)', 'Screening platform (import)']
  };
  const anciennes = { 'zotero': 'reference-library', 'rayyan-import': 'screening-platform-import',
    'covidence-import': 'screening-platform-import' };
  const a = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
  if (typeof s !== 'string') return s == null ? '' : s;
  const k = s.normalize('NFC').trim().toLowerCase();
  let id = a(libelles, k) ? k : (a(anciennes, k) ? anciennes[k] : null);
  if (!id) {
    for (const i of Object.keys(libelles)) {
      if (libelles[i][0].toLowerCase() === k || libelles[i][1].toLowerCase() === k) id = i;
    }
  }
  if (!id) return s;
  return libelles[id][String(lang || '').toLowerCase().indexOf('en') === 0 ? 1 : 0];
}

// ACCORD_LIGNE_UNIQUE_v1 (2026-09-20) : LA LIGNE D'ACCORD DE CE RAPPORT SUIT LA REGLE UNIQUE DU
// DEPOT, celle de src/consolidated_report.py (`_ligne_accord`, `_portee_de_l_accord`) et de l'item 8
// de la checklist (`prisma_checklist._precision_publiee`), etablie par le commit 304cae44.
//
// TROIS ECARTS MESURES LE 2026-09-20, chaine entiere sur les vrais noeuds, sur les etats que le
// VRAI producteur ecrit (« Double Screen Kappa ») :
//   - 12 paires d'une seule categorie : cette pastille etait ABSENTE, alors que le meme run
//     declarait dans methods.json 12 paires, 100 % d'accord, AC1 = 1 et PABAK = 1. Une double
//     lecture reellement faite et reellement mesuree ne paraissait nulle part dans le document ;
//   - 12 paires jugees sur 18 references, et 2 paires sur 18 : la pastille publiait
//     « Cohen kappa = 1 (almost perfect) » sans dire SUR COMBIEN elle porte, donc lisible comme
//     l'accord de toute la revue ;
//   - ni AC1 ni PABAK n'etaient publies, alors que le bloc les porte, et rien ne disait qu'ils
//     manquaient.
// La regle du depot dit l'inverse des trois : les trois indices sont publies, un indice que le bloc
// ne porte pas est DIT et jamais tu, et la portee precede les indices.
//
// LA LANGUE DU DOCUMENT EST MESUREE, PAS SUPPOSEE : ce rapport s'ouvre par <html lang="en"> et tous
// ses titres sont anglais. Les libelles d'interpretation du producteur sont anglais eux aussi : ils
// ne tombent donc pas dans une phrase francaise, et on les garde. C'est pourquoi la regle est suivie
// dans sa STRUCTURE et non dans ses mots francais, qui sont ceux des quatre rapports du relais.
// L'interpretation ne parait qu'A COTE D'UNE VALEUR PUBLIEE, comme l'item 8 le fait.
//
// CE QUE LE BLOC DE CE PRODUCTEUR NE PORTE PAS, mesure le meme jour sur la sortie du vrai noeud :
// aucune cle `*_ci_low`, `*_ci_high`, `ci_level`, `ci_note_en`, `n_first_rated` ni `selection`
// (0 occurrence). Les trois pieces qui les lisent ci-dessous sont donc la REGLE transcrite, et
// aucun etat de ce producteur ne les atteint aujourd'hui : elles sont ecrites pour qu'un bloc qui
// gagnerait ces cles soit publie au lieu d'etre tronque en silence, et elles sont declarees comme
// non eprouvees plutot que gardees par un cas fabrique. La note de methode, elle, n'est PAS
// transcrite : c'est une phrase du producteur, et la phrase entre crochets nomme deja le niveau.
function __accordMesure(b) {
  // ACCORD_MESURE_v1, la MEME regle que « Build Export » du meme run : actif et au moins une paire
  // mesuree, SANS condition sur le kappa. Deux ecrivains du meme bloc ne peuvent pas diverger :
  // exiger un kappa chiffre effacait du rapport une double lecture que methods.json declarait.
  return !!(b && b.enabled && typeof b.n_double_rated === 'number' && b.n_double_rated > 0);
}
// UN NOMBRE FINI, ET SON ECRITURE. `agreement.ecrire_nombre` se declare MIROIR de `String` en
// JavaScript : ici, c'est donc `String` lui-meme. Ni booleen, ni NaN, ni infini, ni chaine ;
// le zero signe s'ecrit « 0 », comme String(-0).
function __pNbAccord(v) { return (typeof v === 'number' && isFinite(v)) ? v : null; }
function __pEcrireAccord(v) { return (__pNbAccord(v) === null) ? null : String(v); }
function __pEntierAccord(v) {
  return (typeof v === 'number' && isFinite(v) && Math.floor(v) === v && v >= 0) ? v : null;
}
// `agreement.intervalle_publiable` : la valeur existe, les deux bornes sont des nombres, la haute
// DEPASSE la basse, et les deux vivent dans [-1 ; 1]. Une largeur nulle n'est pas une precision.
function __pBornesAccord(b, cle) {
  if (__pEcrireAccord(b[cle]) === null) return null;
  const basA = __pNbAccord(b[cle + '_ci_low']), hautA = __pNbAccord(b[cle + '_ci_high']);
  if (basA === null || hautA === null || !(hautA > basA) || basA < -1 || hautA > 1) return null;
  return ' [' + String(basA) + ' ; ' + String(hautA) + ']';
}
// `agreement.niveau_publie` : une proportion est ramenee en pour cent AVANT l'arrondi, l'arrondi
// est celui de l'ecran (le demi monte), et la borne ouverte ]0 ; 100[ porte sur le nombre IMPRIME.
// Aucun niveau invente : sans niveau lisible, la phrase ne porte pas de nombre.
function __pNiveauAccord(b) {
  const vA = __pNbAccord(b.ci_level);
  if (vA === null) return null;
  const rA = Math.round(vA > 1 ? vA : 100 * vA);
  return (rA > 0 && rA < 100) ? rA : null;
}
// `_portee_de_l_accord` : le nombre juge par les deux, le denominateur quand il DEPASSE ce nombre,
// et la selection restreinte quand elle est declaree. Rien n'est imprime d'un effectif illisible.
function __pPorteeAccord(b) {
  const out = [];
  const n2A = __pEntierAccord(b.n_double_rated);
  if (n2A !== null) {
    let tA = n2A + (n2A <= 1 ? ' record' : ' records') + ' rated by both';
    const n1A = __pEntierAccord(b.n_first_rated);
    if (n1A !== null && n1A > n2A) tA += ' of ' + n1A;
    out.push(tA);
  }
  const selA = b.selection;
  if (selA && selA !== 'tous') {
    out.push('restricted selection (' + __pEsc(b.selection_label_en || selA)
      + '), the agreement covers this selection only');
  }
  // RESTE OUVERT : LA STRUCTURE DE CETTE PORTEE DIVERGE DES DEUX AUTRES ECRIVAINS DE LA MEME
  // REGLE (declaration, 2026-09-18). Mesure sur les trois sources : la regle du depot,
  // `_portee_de_l_accord` de src/consolidated_report.py, rend `", ".join(morceaux)`, soit UN
  // segment ou les morceaux sont joints par une virgule ; la pastille du module rend
  // `[out.join(', ')]`, la meme chose ; cette ligne-ci rend `out`, donc des segments SEPARES,
  // joints ensuite par le point median. Sur une portee A PLUSIEURS MORCEAUX les trois ne se
  // liraient donc pas pareil. Etat inatteignable aujourd'hui, et c'est mesure : 0 occurrence de
  // `selection` dans les deux producteurs du bloc (ultralab-screening.json et
  // ultralab-fulltext.json), donc le second morceau n'est jamais bati. Rien n'est change ici :
  // aucun cas ne pourrait eprouver le remede, et un changement sans mesure vaut moins que la
  // declaration.
  return out;
}
const __INDICES_ACCORD = [['cohen_kappa', 'Cohen kappa'], ['gwet_ac1', 'AC1'], ['pabak', 'PABAK']];
function __pLigneAccord(b) {
  const morceaux = __pPorteeAccord(b);
  let avecIC = false;
  for (let iA = 0; iA < __INDICES_ACCORD.length; iA++) {
    const cleA = __INDICES_ACCORD[iA][0], nomA = __INDICES_ACCORD[iA][1];
    const valeurA = __pEcrireAccord(b[cleA]);
    let tA;
    if (valeurA === null) {
      // UN INDICE QUE LE BLOC NE PUBLIE PAS EST DIT, JAMAIS TU.
      tA = '<b>' + nomA + ' not published</b>';
    } else {
      let teteA = nomA + ' = ' + valeurA;
      const bornesA = __pBornesAccord(b, cleA);
      if (bornesA) { teteA += bornesA; avecIC = true; }
      tA = '<b>' + teteA + '</b>';
      if (cleA === 'cohen_kappa' && b.kappa_interpretation) {
        tA += ' (' + __pEsc(b.kappa_interpretation) + ')';
      }
    }
    if (cleA === 'cohen_kappa') {
      const tauxA = __pEcrireAccord(b.percent_agreement);
      if (tauxA !== null) tA += ', agreement ' + tauxA + '%';
    }
    morceaux.push(tA);
  }
  let ligneA = morceaux.join(' &middot; ');
  if (avecIC) {
    const nvA = __pNiveauAccord(b);
    ligneA += '. In brackets: confidence interval'
      + ((nvA !== null) ? (' at ' + nvA + '%') : '') + '.';
  }
  return ligneA;
}

// BLOC_ACCORD_SUR_SON_PORTEUR_v1 (2026-09-20) : meme regle que dans « Build Export ». La
// recuperation des PDF place les inclus et les indecis avant les exclus ; le bloc d'accord,
// ecrit sur le premier article du corpus, n'est donc pas toujours au rang zero. Mesure du
// 2026-09-20 : premier article du corpus exclu, 18 paires, kappa 0.769, bloc au rang 8, et la
// pastille disparaissait du rapport.
const __blocAccord = ((articles.find(function (aBA) { return aBA && aBA._screening_kappa; }))
  || {})._screening_kappa;

// ─── Parse LLM text to HTML ───
function textToHtml(text) {
  return text.split('\n').map(line => {
    const l = line.trim();
    if (!l) return '';
    if (l.startsWith('## ')) return '<h2>' + __pEsc(l.substring(3)) + '</h2>';
    if (l.startsWith('### ')) return '<h3>' + __pEsc(l.substring(4)) + '</h3>';
    if (l.startsWith('- ')) return '<li>' + __pEsc(l.substring(2)) + '</li>';
    if (l.startsWith('* ')) return '<li>' + __pEsc(l.substring(2)) + '</li>';
    return '<p>' + __pEsc(l) + '</p>';
  }).join('\n');
}

// ─── Cluster rows ───
const clusterRows = clusters.map(label => {
  const count = articles.filter(a => a.cluster_label === label).length;
  const inc = articles.filter(a => a.cluster_label === label && a.screening_decision === 'Include').length;
  return '<tr><td>' + __pEsc(label) + '</td><td style="text-align:center">' + count + '</td><td style="text-align:center">' + inc + '</td></tr>';
}).join('\n');

// ─── Source rows ───
// LES LIGNES SONT BATIES A UN SEUL ENDROIT, avec l'echappement : celui du tableau du flux, plus
// bas. La construction morte qui batissait ICI du HTML avec la source NON echappee a ete retiree le
// 2026-09-20 ; LE PREDICAT QU'ELLE LAISSAIT L'EST AUSSI, et voici la mesure qui le condamne : ses
// DEUX branches rendaient le MEME document, parce qu'une liste vide rend le predicat faux et que la
// jointure d'une liste vide est la chaine vide. Une condition dont les deux branches ecrivent le
// meme texte ne protege rien, et une mutation qui la force a vrai ne peut etre tuee par aucun cas
// (carnet : « cas protege deux fois », dont le remede est de retirer la protection morte). Le
// tableau du flux ne porte donc aucune ligne de source quand le corpus n'en declare aucune : c'est
// exactement ce que l'utilisateur lisait deja.

// ─── Top included articles ───
const topArticles = articles
  .filter(a => a.screening_decision === 'Include')
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, 15)
  .map(a => '<tr><td>' + __pEsc((a.title || '').substring(0, 80)) + '</td><td>' + __pEsc(Array.isArray(a.authors) ? a.authors.slice(0, 3).join(', ') : '') + '</td><td style="text-align:center">' + __pEsc(a.year || '') + '</td><td style="text-align:center">' + __pEsc(a.score || '') + '</td><td>' + __pEsc(a.cluster_label || '') + '</td></tr>')
  .join('\n');

// TEXTES_DU_DOCUMENT_ANGLAIS_v1 (2026-09-20) : CE DOCUMENT EST ANGLAIS, mesure et non suppose (il
// s'ouvre par <html lang="en"> et tous ses titres le sont), et trois libelles FRANCAIS y
// subsistaient dans des surfaces vues par l'utilisateur : les cartes « Inclusion probable » et
// « Non-inclusion probable » du resume de pre-screening, et le nom de colonne cite pour le classeur.
//   - les deux cartes passent en anglais, comme les deux autres de la meme rangee ;
//   - LE NOM DE COLONNE N'EST PAS TRADUIT, IL EST CORRIGE. C'est un nom propre : celui que le
//     producteur ecrit dans l'entete du classeur. Mesure du 2026-09-20 sur « Build Export » de
//     ultralab-export.json, entete relu dans le fichier : la colonne s'appelle « Critère Ranking »,
//     avec son accent, quand ce document la citait « Critere Ranking ». Le rapport renvoyait donc a
//     une colonne qui n'existe sous aucun nom. La traduire l'aurait rendue introuvable ; la renommer
//     dans le classeur changerait l'entete de tous les classeurs produits, ce qui sort de ce lot.
//     On cite le producteur a l'octet, et un cas relit les deux cotes.
// ─── Build complete HTML ───
const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PRISMA 2020 - Systematic Review Report</title>
<style>
  @page { size: A4; margin: 2cm; }
  body { font-family: 'Segoe UI', Calibri, Arial, sans-serif; max-width: 900px; margin: 0 auto; padding: 40px 20px; color: #333; line-height: 1.6; }
  .cover { text-align: center; padding: 80px 0 60px 0; border-bottom: 3px solid #4472C4; margin-bottom: 40px; }
  .cover h1 { color: #4472C4; font-size: 2.5em; margin-bottom: 10px; }
  .cover .subtitle { color: #666; font-size: 1.3em; margin-bottom: 30px; }
